var a=`0861-jalebi`;var t=`world-0861`;var n=`IN`;var r=`south-asia`;var o=8;var l=134;var s={en:`Jalebi`,ua:`Джалебі`};var u={en:`Jalebi is a India dish made with all-purpose flour, plain yogurt. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Джалебі, страва кухні країни Індія. Основні складники: пшеничне борошно універсальне, натуральний йогурт. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var d=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:10,i:[[`all-purpose-flour`,230,`g`],[`plain-yogurt`,95,`g`],[`water`,160,`ml`],[`ground-turmeric`,2,`g`]]},{en:`Cover the batter loosely and leave in a suitable warm, clean place for about 90 minutes to become bubbly and lightly tangy; do not refrigerate during active fermentation.`,ua:`Нещільно накрийте тісто й залиште приблизно на 90 хвилин у чистому теплому місці до появи бульбашок і легкої кислинки; під час активного бродіння не ставте в холодильник.`,t:[`sourdough-fermentation`],m:90,i:[]},{en:`Fry shaped portions in small batches in oil heated to about 170–175°C for about 18 minutes, until golden; drain on a rack.`,ua:`Смажте сформовані вироби невеликими партіями в олії температурою приблизно 170–175°C близько 18 хвилин до золотистості; викладіть на решітку.`,t:[`deep-frying`],m:18,i:[[`canola-oil`,650,`ml`]]},{en:`Boil sugar and water briefly into a light saffron syrup; do not caramelize it.`,ua:`Недовго проваріть цукор із водою до легкого шафранового сиропу, не карамелізуйте.`,t:[`reducing-sauce`],m:12,i:[[`white-granulated-sugar`,320,`g`],[`water`,230,`ml`],[`saffron-threads`,1,`pinch`]]},{en:`Dip freshly fried jalebi spirals in warm syrup only briefly, then drain for a crisp sweet shell.`,ua:`Коротко занурте щойно обсмажені спіралі джалебі в теплий сироп і дайте стекти, щоб оболонка залишилася хрусткою.`,t:[`sugar-syrup-cooking`],m:4,i:[]}];var g={slug:a,id:t,country:`IN`,region:r,servings:8,minutes:134,title:s,text:u,steps:d};export{n as country,g as default,t as id,l as minutes,r as region,o as servings,a as slug,d as steps,u as text,s as title};